script:
git init -q; printf 'int main() {
  int a;
  int b;
  int c;
  int d;
  return 0;
}
' > m.c; git add .; git commit -qm one; sed -i 's/int c;/int c = 1;/' m.c; git diff

stdout:
diff --git a/m.c b/m.c
index a7a9f35..e70b743 100644
--- a/m.c
+++ b/m.c
@@ -1,7 +1,7 @@
 int main() {
   int a;
   int b;
-  int c;
+  int c = 1;
   int d;
   return 0;
 }

